// Import of required libraries
import { test, checkRequestPayload, expect, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { URL_app, deleteVisit, fillVisitForm, submitVisitForm } from './skyrampUtils';

const pageTimeout = 15000;

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(341000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    // Expected request payloads for network assertions
    const expectedPayload1 = {
        "date": "2026-09-08",
        "description": "Annual wellness exam and rabie",
        "pet": {
            "birthDate": "2010-09-07",
            "name": "Leo",
            "ownerId": 1,
            "type": {"name": "cat"}
        }
    };

    // Navigate without the /petclinic base href: that prefix is proxied to the
    // REST service, so the app must be entered on the unproxied path and left to
    // rewrite the URL itself.
    await page.goto(`${URL_app}/pets/1/visits/add`);
    await expect(page.locator("#date")).toBeVisible();

    await fillVisitForm(page, "2026/09/08", "Annual wellness exam and rabies booster!");
    // The browser refuses the 10 characters past maxlength=30, so the field holds
    // only the first 30 -- under the old maxlength=255 it would hold all 40.
    await expect(page.getByRole("textbox", { name: "Description" })).toHaveValue("Annual wellness exam and rabie");

    const response0 = await submitVisitForm(page);
    // Validate request payload
    checkRequestPayload(response0.request().postDataJSON(), expectedPayload1);

    expect(response0.status(), 'add visit status').toBe(201);
    const createdVisit = await response0.json();
    expect(createdVisit.description, 'saved description').toBe("Annual wellness exam and rabie");
    expect(createdVisit.description.length, 'saved description length').toBe(30);
    expect(createdVisit.petId, 'saved petId').toBe(1);
    expect(createdVisit.date, 'saved date').toBe("2026-09-08");
    expect(createdVisit.id, 'saved id').toBeGreaterThan(0);

    // Reaching the owner detail page is itself the outcome: the component only
    // navigates here from the save-success branch of addVisit().
    await expect(page).toHaveURL(/\/petclinic\/owners\/1$/);
    await expect(page.getByRole("heading", { name: "Owner Information" })).toBeVisible();

    // Remove the visit this test created so it leaves no record behind.
    const deleteResponse = await deleteVisit(page, createdVisit.id);
    expect(deleteResponse.status(), 'cleanup delete status').toBe(204);
});
